SELECT SUM(pizza_clean_customer_orders.extras) + SUM(pizza_clean_customer_orders.pizza_id * (CASE WHEN pizza_clean_customer_orders.pizza_id = 1 THEN 12 ELSE 10 END)) AS total_earnings
FROM pizza_clean_customer_orders
WHERE pizza_clean_customer_orders.pizza_id IN (1, 2)
AND pizza_clean_customer_orders.order_id NOT IN (
    SELECT order_id FROM pizza_clean_runner_orders WHERE cancellation = 'Yes'
);

SELECT T1.EntStageName, T2.CustLastName
FROM Entertainers AS T1
JOIN Musical_Preferences AS T2 ON T1.EntertainerID = T2.CustomerID
WHERE (
    (T2.StyleID = 1 AND T2.StyleStrength <= 3) OR
    (T2.StyleID = 2 AND T2.StyleStrength <= 3)
) AND (
    (T2.PreferenceSeq = 1 AND T1.StyleStrength <= 3) OR
    (T2.PreferenceSeq = 2 AND T1.StyleStrength <= 3)
);
